import {AbstractLayout, HtmlComponent} from '../index';
import $ from 'jquery';

/**
 * Null Layout.
 */
export default class NullLayout extends AbstractLayout {

  constructor() {
    super();
  }

  layout($container) {
    $container.children().each(function() {
      var htmlComp = HtmlComponent.optGet($(this));
      if (htmlComp) {
        htmlComp.revalidateLayout();
      }
    });
  }
}
